const existing = h.$$('textarea, [contenteditable="true"], [contenteditable=""], [role="textbox"]').find(e => h.visible(e));
if (existing) return state;
const ctl = h.$('[role="link"][aria-label="Respond"]') || h.findByText(/^\s*Respond\s*$/i);
if (!ctl) throw new Error('No Respond control found in the open email view');
h.click(ctl);
const box = await h.waitFor(() => h.$$('textarea, [contenteditable="true"], [contenteditable=""], [role="textbox"]').find(e => h.visible(e)), 6000);
if (!box) throw new Error('Clicked Respond but no editable reply box appeared');
return state;

const findBox = () => h.$$('textarea, [contenteditable="true"], [contenteditable=""], [role="textbox"]').find(e => h.visible(e));
if (findBox()) return state;
const findExpander = () => h.$$('[aria-label="Expand composer"], [role="button"][aria-expanded="false"]').find(e => h.visible(e) && /expand|composer|reply/i.test((e.getAttribute('aria-label') || '') + ' ' + (e.textContent || '')));
let exp = findExpander();
if (!exp) {
  const ctl = h.$('[role="link"][aria-label="Respond"]') || h.findByText(/^\s*(Respond|Reply)\s*$/i);
  if (!ctl) throw new Error('No Respond/Reply control or composer expander found in the open email view');
  h.click(ctl);
  const got = await h.waitFor(() => findBox() || findExpander(), 6000);
  if (got && findBox()) return state;
  exp = findExpander();
}
if (!exp) throw new Error('No editable reply box and no collapsed composer expander found after Respond');
h.click(exp);
let box = await h.waitFor(findBox, 6000);
if (!box) {
  const again = findExpander();
  if (again) { h.click(again); box = await h.waitFor(findBox, 4000); }
}
if (!box) throw new Error('Expanded the collapsed composer (aria-label="Expand composer") but no editable reply box appeared');
return state;

